import test from "node:test";
import assert from "node:assert/strict";
import { createTestEnvironment } from "./helpers/fakeDom.js";
import { createEmptyMapDefinition, setLegacyTileAt } from "../src/domain/map/mapModel.js";
import { createMapUpgradeDraft, beginMapUpgrade } from "../src/domain/map/mapUpgrade.js";
import { decodeMapDefinition, encodeMapDefinition } from "../src/domain/map/mapCodec.js";
import { RAMP_TILE_TYPES } from "../src/domain/map/bridgeTopology.js";
import { STORAGE_KEYS } from "../src/storage/mapStore.js";

const original = createEmptyMapDefinition();
[[0, 0, "POLICE_SPAWN"], [9, 9, "THIEF_SPAWN"], [0, 9, "BANK"], [9, 0, "THIEF_BASE"], [4, 4, "OVERPASS"]]
  .forEach(([r, c, type]) => setLegacyTileAt(original, r, c, type));
const originalRecord = { id: "original", name: "原桥图", encodedMap: encodeMapDefinition(original), updatedAt: 1, schemaVersion: 3 };
const draft = beginMapUpgrade(createMapUpgradeDraft({ encodedMap: originalRecord.encodedMap, mapId: originalRecord.id }));
RAMP_TILE_TYPES.forEach((type, index) => setLegacyTileAt(draft, 2, index + 2, type));
const encodedMap = encodeMapDefinition(draft);
const env = createTestEnvironment({ search: `?m=${encodedMap}` });
env.installGlobals();
env.localStorage.setItem(STORAGE_KEYS.mapList, JSON.stringify([originalRecord]));
env.localStorage.setItem(STORAGE_KEYS.currentMapId, originalRecord.id);
const { init } = await import("../src/app/bootstrap.js");
const { state } = await import("../src/app/state.js");
const { clearMap, undoMap, redoMap } = await import("../src/features/editorController.js");
const { getMapList, getCurrentMapId, createMapBackup, persistCurrentMap, retryMapSave } = await import("../src/storage/mapRepository.js");

test("a shared upgrade draft displays all directions and stays separate from the original through edit, clear, undo and failed saves", () => {
  init();
  assert.equal(getMapList().length, 2);
  assert.notEqual(getCurrentMapId(), originalRecord.id);
  assert.equal(state.mapDefinition.upgrade.status, "editing");
  assert.deepEqual(getMapList().find((record) => record.id === originalRecord.id), originalRecord);
  assert.deepEqual(env.elements["editor-board"].querySelectorAll(".bridge-ramp-sign").map((sign) => sign.dataset.direction), ["N", "E", "S", "W"]);
  assert.equal(env.elements.palette.querySelectorAll(".palette-item").some((item) => RAMP_TILE_TYPES.includes(item.dataset.type)), true);
  env.elements["btn-start-game"].click();
  assert.equal(state.mode, "EDITOR");
  assert.match(env.alerts.at(-1), /校验并完成升级/);
  const savedUpgrade = structuredClone(state.mapDefinition.upgrade);
  clearMap();
  assert.deepEqual(state.mapDefinition.upgrade, savedUpgrade);
  assert.equal(state.mapDefinition.ruleset, "ramps");
  assert.equal(env.elements["editor-board"].querySelectorAll(".bridge-ramp-sign").length, 0);
  undoMap();
  assert.equal(env.elements["editor-board"].querySelectorAll(".bridge-ramp-sign").length, 4);
  redoMap();
  assert.deepEqual(state.mapDefinition.upgrade, savedUpgrade);
  const realSet = env.localStorage.setItem;
  env.localStorage.setItem = () => { throw new DOMException("full", "QuotaExceededError"); };
  setLegacyTileAt(state.mapDefinition, 2, 2, "OVERPASS_RAMP_N");
  persistCurrentMap();
  assert.equal(env.elements["storage-notice"].classList.contains("hidden"), false);
  const backup = createMapBackup();
  assert.deepEqual(decodeMapDefinition(backup.currentMap.encodedMap).upgrade, savedUpgrade);
  env.localStorage.setItem = realSet;
  retryMapSave();
  const current = getMapList().find((record) => record.id === getCurrentMapId());
  assert.equal(current.schemaVersion, 4);
  assert.equal(decodeMapDefinition(current.encodedMap).terrain[2][2], "OVERPASS_RAMP_N");
  assert.deepEqual(decodeMapDefinition(current.encodedMap).upgrade, savedUpgrade);
  assert.deepEqual(getMapList().find((record) => record.id === originalRecord.id), originalRecord);
});
